-- [JLAS-W0260] Kana Connect demo leaderboard - DEVELOPMENT/DEMO ONLY, never import on production.
-- Adds 14 fictional learners (no password, unverified, reserved .invalid e-mail domain) and their
-- progress on every Kana Connect board that already exists for today (Asia/Ho_Chi_Minh day).
-- Boards are generated by the app: open each level once (N5..N1, Trộn) before running this file.
-- Re-runnable: refreshes the demo rows for today's boards; real learners are never touched.
-- Times are written as UTC wall-clock values, matching how the app stores TIMESTAMP columns.
SET NAMES utf8mb4;

SET @kana_demo_day = DATE(CONVERT_TZ(UTC_TIMESTAMP(), '+00:00', '+07:00'));
SET @kana_demo_role = (SELECT id FROM roles WHERE name = 'LEARNER');

DROP TEMPORARY TABLE IF EXISTS kana_demo_user;
CREATE TEMPORARY TABLE kana_demo_user (
    n         INT NOT NULL PRIMARY KEY,
    email     VARCHAR(255) NOT NULL,
    username  VARCHAR(50) NOT NULL,
    full_name VARCHAR(150) NOT NULL,
    level     VARCHAR(10) NOT NULL
) DEFAULT CHARSET = utf8mb4 COLLATE = utf8mb4_unicode_ci;

