INSERT INTO users (role_id, email, username, password_hash, login_type, full_name, japanese_level,
                   is_verified, created_at, updated_at)
SELECT @kana_demo_role, d.email, d.username, NULL, 'LOCAL', d.full_name, d.level, 0,
       UTC_TIMESTAMP(6) - INTERVAL 30 DAY, UTC_TIMESTAMP(6) - INTERVAL 30 DAY
FROM kana_demo_user d LEFT JOIN users u ON u.email = d.email
WHERE u.id IS NULL AND @kana_demo_role IS NOT NULL;

-- Per board: about four in five demo learners finished (varied times, so the ranking spreads);
-- the rest are mid-game with two words found and stay off the leaderboard.
DROP TEMPORARY TABLE IF EXISTS kana_demo_progress;
CREATE TEMPORARY TABLE kana_demo_progress AS
SELECT u.id AS user_id, p.id AS puzzle_id, p.challenge_date, p.board_level, p.puzzle_json,
       (d.n + p.id) % 5 <> 0 AS finished,
       45 + ((d.n * 37 + p.id * 53) % 420) AS elapsed,
       600 + d.n * 240 + p.id * 30 AS started_ago
FROM daily_kana_puzzle p
JOIN kana_demo_user d
JOIN users u ON u.email = d.email
WHERE p.challenge_date = @kana_demo_day;

INSERT INTO daily_kana_challenge
    (user_id, challenge_date, puzzle_id, vocabulary_id, jlpt_level, mixed_levels, expression, reading, meaning,
     cells_json, solution_json, started_at, completed_at, elapsed_seconds)
SELECT g.user_id, g.challenge_date, g.puzzle_id,
       JSON_EXTRACT(g.puzzle_json, '$.words[0].id'), g.board_level, g.board_level = 'MIX',
       JSON_UNQUOTE(JSON_EXTRACT(g.puzzle_json, '$.words[0].expression')),
       JSON_UNQUOTE(JSON_EXTRACT(g.puzzle_json, '$.words[0].reading')),
       JSON_UNQUOTE(JSON_EXTRACT(g.puzzle_json, '$.words[0].meaning')),
       '',
       IF(g.finished,
          JSON_OBJECT('solvedWordIds', JSON_EXTRACT(g.puzzle_json, '$.words[*].id')),
          JSON_OBJECT('solvedWordIds', JSON_ARRAY(JSON_EXTRACT(g.puzzle_json, '$.words[0].id'),
                                                  JSON_EXTRACT(g.puzzle_json, '$.words[1].id')))),
       UTC_TIMESTAMP(6) - INTERVAL g.started_ago SECOND,
       IF(g.finished, UTC_TIMESTAMP(6) - INTERVAL (g.started_ago - g.elapsed) SECOND, NULL),
       IF(g.finished, g.elapsed, NULL)
FROM kana_demo_progress g
ON DUPLICATE KEY UPDATE solution_json = VALUES(solution_json), started_at = VALUES(started_at),
                        completed_at = VALUES(completed_at), elapsed_seconds = VALUES(elapsed_seconds);

SELECT p.board_level AS board, COUNT(c.id) AS demo_rows, SUM(c.completed_at IS NOT NULL) AS finished
FROM daily_kana_puzzle p
LEFT JOIN daily_kana_challenge c ON c.puzzle_id = p.id
    AND c.user_id IN (SELECT u.id FROM users u JOIN kana_demo_user d ON d.email = u.email)
WHERE p.challenge_date = @kana_demo_day
GROUP BY p.board_level ORDER BY p.board_level;

DROP TEMPORARY TABLE IF EXISTS kana_demo_progress;
DROP TEMPORARY TABLE IF EXISTS kana_demo_user;

